import pytest
from fastapi import FastAPI
from fastapi.routing import APIRoute
from fastapi.testclient import TestClient
from pydantic import BaseModel


class Item(BaseModel):
    name: str = "item"
    description: str | None = None
    price: float | None = None


@pytest.mark.parametrize(
    "registration",
    ["get", "post", "put", "patch", "delete", "options", "head", "trace",
     "api_route", "add_api_route"],
)
@pytest.mark.parametrize("default", [True, False, None])
def test_global_exclude_none(registration: str, default: bool | None):
    app = (
        FastAPI()
        if default is None
        else FastAPI(default_response_model_exclude_none=default)
    )
    assert app.default_response_model_exclude_none is bool(default)

    def get_item() -> Item:
        return Item()

    register = getattr(app, registration)
    for path, options in [
        ("/item", {}),
        ("/include-none", {"response_model_exclude_none": False}),
        ("/exclude-none", {"response_model_exclude_none": True}),
    ]:
        if registration == "add_api_route":
            register(path, get_item, response_model=Item, **options)
        else:
            register(path, response_model=Item, **options)(get_item)

    method = (
        "get" if registration in {"api_route", "add_api_route"} else registration
    )
    with TestClient(app) as client:
        for path, exclude_none in [
            ("/item", bool(default)),
            ("/include-none", False),
            ("/exclude-none", True),
        ]:
            route = next(
                route
                for route in app.routes
                if isinstance(route, APIRoute) and route.path == path
            )
            assert route.response_model_exclude_none is exclude_none
            response = client.request(method, path)
            assert response.status_code == 200
            if method != "head":
                expected = {"name": "item"}
                if not exclude_none:
                    expected.update(description=None, price=None)
                assert response.json() == expected
